export const renameHostResponseCapacityTwoDiskReclaimableMbMin = 0;

export const renameHostResponseCapacityTwoDiskTotalMbMin = 0;

export const renameHostResponseCapacityTwoDiskUsedMbMin = 0;

export const renameHostResponseCapacityTwoMemoryMbMin = 0;

export const renameHostResponseCapacityTwoMemoryUsedMbMin = 0;

export const renameHostResponseComputeThreePortMin = 0;

export const renameHostResponseCpusMin = 0;

export const renameHostResponseMemoryMbMin = 0;



export const RenameHostResponse = zod.object({
  "capacity": zod.union([zod.null(),zod.object({
  "diskCachedImagesMb": zod.int().min(renameHostResponseCapacityTwoDiskCachedImagesMbMin).describe('Images no container is currently using.\n\nDocker\'s own reclaimable figure, kept apart from the safe one because\nclearing it is a real choice: nothing is lost, but the next session\nwanting postgres waits for the pull again.'),
  "diskFiretowerMb": zod.int().min(renameHostResponseCapacityTwoDiskFiretowerMbMin).describe('Of that, what Firetower is using: images its sessions pulled, the cache\ntheir builds left, the containers they started.\n\nSeparate from `disk_used_mb` because the difference is the whole of\nwhose mess it is. The machine\'s disk is the operator\'s business; this\npart is ours, and it is the only part anything here offers to clear.'),
  "diskReclaimableMb": zod.int().min(renameHostResponseCapacityTwoDiskReclaimableMbMin).describe('What clearing the build cache would give back.\n\nRebuildable by definition, so this is the figure safe to offer without\nqualification: it costs one slower build and nothing else.\n\nDeliberately not Docker\'s own `RECLAIMABLE`, which counts every image no\ncontainer happens to be running — on a daemon shared by every session on\na worker, that is every image the next session was about to use, and\noffering it as free space would empty the cache the worker\'s volume\nexists to keep.'),
  "diskTotalMb": zod.int().min(renameHostResponseCapacityTwoDiskTotalMbMin).describe('Where the daemon keeps images, which on most workers is also the disk\nthe worker itself is on.'),
  "diskUsedMb": zod.int().min(renameHostResponseCapacityTwoDiskUsedMbMin),
  "memoryMb": zod.int().min(renameHostResponseCapacityTwoMemoryMbMin).describe('What the machine has, or the ceiling the worker container was given.'),
  "memoryUsedMb": zod.int().min(renameHostResponseCapacityTwoMemoryUsedMbMin)
}).describe('What this machine has and what is being used of it.\n\n`None` from a worker too old to report it, which the interface draws as\nno capacity block rather than as an empty one.')]).optional(),
  "compute": zod.union([zod.object({
  "type": zod.enum(['Local'])
}).describe('A worker as a child process here. Inherits your environment, and its\nworkspaces are directories you can open.'),zod.object({
  "image": zod.string(),
  "name": zod.string(),
  "type": zod.enum(['Container'])
}).describe('A worker in a container here. Linux, and isolated from your machine.\n\nReached with `docker exec` rather than ssh: the same bidirectional pipe\nwithout an sshd, a key, or a host key to verify.'),zod.object({
  "container": zod.string().nullish().describe('The container the worker runs in on that machine. Absent runs the\nbinary on the host itself, for a machine whose image already has it.\n\nReached by ssh-ing to the machine and running `docker exec` there,\nnever by ssh-ing into the container — that would need a key inside\nthe image, a published port, and a host key that changes on every\nrecreate.'),
  "host": zod.string().describe('A hostname, an address, or a name from your ssh config.'),
  "hostKey": zod.string().nullish().describe('Recorded when the host is added. Not yet checked against what the\nmachine answers with — connecting trusts a key it hasn\'t seen before\nand remembers it, so this is a record rather than a guarantee.'),
  "key": zod.union([zod.object({
  "type": zod.enum(['Default'])
}).describe('Let ssh choose: the agent first, then the usual names in `~\/.ssh`.\n\nThe default, and what an absent `identity_file` used to mean. Still\nuseful for a control plane running on a machine whose ssh is already\nconfigured — a development install, or a binary on a host.'),zod.object({
  "type": zod.enum(['Managed'])
}).describe('The key Firetower made for itself, sealed in the vault.\n\nWhat a server added through the interface uses. Firetower holds this one\nbecause in a container there is no other way for it to hold anything:\nit is scoped to this installation, opens nothing else, and is revoked by\ndeleting one line on one machine.'),zod.object({
  "name": zod.string(),
  "type": zod.enum(['Held'])
}).describe('A private key the operator pasted, sealed in the vault under this name.\n\nFor an existing key they would rather reuse, or one signed by a CA.'),zod.object({
  "path": zod.string(),
  "type": zod.enum(['File'])
}).describe('A path on the machine running the control plane.\n\nStill correct when that machine is not a container. Kept so that every\nhost added before this existed keeps working and means what it did.')]).optional().describe('Which key to authenticate with. See [`SshKey`].'),
  "port": zod.int().min(renameHostResponseComputeThreePortMin).nullish().describe('Absent is whatever ssh would use: 22, or what the config says.'),
  "type": zod.enum(['Server']),
  "user": zod.string().nullish().describe('Who to connect as.\n\nAbsent leaves it to ssh, which is what keeps a name from your ssh\nconfig working on its own — that file may already say, and repeating\nit here badly is worse than not repeating it.')
}).describe('A worker on another machine. What a real deployment looks like.\n\nHeld as the parts of an ssh destination rather than one string, because\neach part is a separate decision: the address is the machine, the user is\nthe account work runs as, and the key is which of several you keep.\nAssembling them is [`Compute::ssh_destination`]\'s job.')]),
  "cpus": zod.int().min(renameHostResponseCpusMin).nullish(),
  "diagnosis": zod.union([zod.null(),zod.object({
  "at": zod.iso.datetime({"offset":true}),
  "cause": zod.enum(['WorkerMissing', 'DockerMissing', 'DockerDenied', 'ContainerMissing', 'AuthRefused', 'Unreachable', 'HostKeyChanged', 'ProtocolMismatch', 'Unknown']).describe('What went wrong, at the granularity of what fixes it.'),
  "detail": zod.string().nullish().describe('What the far end actually said, verbatim.\n\nKept even when the cause is recognised: the summary is an inference\nabout another machine, and this is what survives it being wrong.'),
  "remedy": zod.string().nullish().describe('What to run, when there is something to run. Shown with a copy button,\nso it must be the whole command and nothing else.'),
  "summary": zod.string().describe('One sentence, written for whoever is looking at the screen.')
}).describe('Why it isn\'t answering, when it isn\'t. Cleared as soon as it does.')]).optional(),
  "docker": zod.object({
  "detail": zod.string().nullish().describe('The daemon\'s version where it is running, and why it isn\'t where it\nisn\'t. Absent when there is nothing to add: a machine with no Docker on\nit has said everything there is to say.'),
  "status": zod.enum(['Unknown', 'Running', 'Stopped', 'Absent']).describe('The four answers to \"can a session here run a container?\".\n\nTwo kinds of no, because they have different fixes and an agent told only\n\"no\" keeps trying. The distinction that matters is between a machine where\nDocker was never meant to be and one where it was and did not start.')
}).optional().describe('Whether a session on this machine can run containers.\n\nReported by the worker at every handshake rather than inferred from the\nkind of host: the answer is a fact about the machine the worker is on,\nand a container, a server and a server-with-a-container each arrive at\nit differently.'),
  "drained": zod.boolean().optional().describe('Finishing what it has, taking nothing new. Separate from being\nunreachable: a draining host is still online and still working.'),
  "id": zod.string().describe('Identifies a host.'),
  "memoryMb": zod.int().min(renameHostResponseMemoryMbMin).nullish(),
  "name": zod.string().describe('What the user calls it. `localhost` is a real host, not a special case.'),
  "reconnecting": zod.boolean().optional().describe('Whether we are still trying to reach it.\n\nA fact about the running control plane rather than about the host, so it\nis answered per request and never stored. Distinguishes a machine on its\nway back from one nobody is looking for.'),
  "state": zod.enum(['Online', 'Unreachable', 'Draining']),
  "workerVersion": zod.string().nullish()
}).describe('A machine that can run workspaces.')

/**
 * The supervisor would get there on its own; this is for the moment just after
 * you have fixed the machine and would rather not wait.
 * @summary Try a host again now, instead of waiting out the backoff.
 */
export const ConnectHostParams = zod.object({
  "id": zod.string().describe('Host id')
})

export const ConnectHostResponse = zod.void()

/**
 * @summary Stop sending work here, or start again.
 */
export const DrainHostParams = zod.object({
  "id": zod.string().describe('Host id')
})

export const DrainHostBody = zod.object({
  "drained": zod.boolean()
})

export const DrainHostResponse = zod.void()

/**
 * Read before adding a server, because the machine has to be given this before
 * it will let Firetower in — and that is a step on the *other* machine, which
 * nothing here can do.
 *
 * There is no companion endpoint for the private half, and there should never
 * be one. It goes from the vault to a file ssh reads and no further.
 * @summary The public half of Firetower's own ssh key.
 */
export const SshKeyResponse = zod.object({
  "algorithm": zod.string(),
  "fingerprint": zod.string().describe('`SHA256:…`, to match against `ssh-keygen -lf` on the other machine when\nthe two disagree about what was installed.'),
  "publicKey": zod.string().describe('`ssh-ed25519 AAAAC3… firetower`, exactly as `authorized_keys` wants it.')
}).describe('What a person may see.\n\nThe private half is not here and is not returned by anything: it goes from\nthe vault to a file ssh reads, and back out of existence. Every field below\nis safe on a screen, in a screenshot, and in a provider\'s web form.')

